"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[4358],{14358:a=>{a.exports=JSON.parse('{"categories":{"prayer-times":"Waktu solat","location":"Lokasi","setup":"Tetapan solat anda","athan":"Azan","scheduled":"Azan automatik","quran":"Al-Quran dan main balik","hifz":"Jurulatih Hafazan","masjid":"Masjid Saya","ramadan":"Ramadan","islamic-calendar":"Kiblat dan kalendar Hijrah","fasting":"Puasa sunat","remembrance":"Zikir, tasbih dan peringatan harian","help":"Bermula"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"Menyebut solat seterusnya, waktunya dan berapa lama lagi, serta waktu iqamah masjid anda jika anda mengikutinya.","say":["Alexa, minta Muslim Companion apakah solat saya seterusnya","Alexa, minta Muslim Companion bilakah solat seterusnya"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Menyebut waktu satu solat hari ini (selepas Isyak, Subuh ialah untuk esok).","say":["Alexa, minta Muslim Companion bilakah Maghrib","Alexa, minta Muslim Companion pukul berapa Subuh"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Membaca semua waktu hari ini. Pada Echo Show ia juga dipaparkan di skrin bersama solat seterusnya dan kiraan detik.","say":["Alexa, minta Muslim Companion waktu solat hari ini","Alexa, minta Muslim Companion waktu solat"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"Menetapkan waktu solat daripada alamat Echo anda (selepas anda membenarkan Alamat Peranti dalam apl Alexa). Hanya bandar dan koordinat anggaran disimpan.","say":["Alexa, minta Muslim Companion guna lokasi Echo saya","Alexa, minta Muslim Companion kemas kini lokasi saya"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"Dalam apl Alexa di telefon: waktu solat di tempat anda berada sekarang, untuk jawapan itu sahaja. Azan di rumah tidak berubah.","say":["Alexa, minta Muslim Companion waktu solat di tempat saya berada","Alexa, minta Muslim Companion waktu solat berhampiran saya"]},"Yes":{"does":"Menjawab soalan daripada Muslim Companion, contohnya sama ada mahu guna lokasi Echo anda.","say":["Ya","Tidak"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Menyebut lokasi, kaedah pengiraan dan mazhab Asar anda, serta cara menukarnya.","say":["Alexa, minta Muslim Companion bacakan tetapan solat saya"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Menukar cara waktu solat dikira: ISNA, Liga Dunia Muslim, Umm al-Qura, Mesir, Karachi, Teluk, Kuwait, Qatar, Singapura, Perancis, Turki, Rusia, Tehran atau Jafari. Alexa mengesahkan dengan waktu solat seterusnya yang baharu dan memberitahu cara untuk kembali.","say":["Alexa, minta Muslim Companion tetapkan kaedah pengiraan saya kepada Umm al-Qura","Alexa, beritahu Muslim Companion untuk guna kaedah Liga Dunia Muslim","Alexa, beritahu Muslim Companion masjid saya guna ISNA"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"Menetapkan waktu Asar: Hanafi (Asar lebih lewat), atau standard bagi Syafie, Maliki dan Hanbali.","say":["Alexa, minta Muslim Companion tetapkan mazhab saya kepada Hanafi","Alexa, beritahu Muslim Companion saya mengikut mazhab Hanafi","Alexa, minta Muslim Companion tetapkan mazhab saya kepada standard"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Mencadangkan kaedah yang paling banyak digunakan di tempat anda (contohnya ISNA di Amerika Utara, Diyanet di Turki) dan menawarkan untuk bertukar: jawab ya atau tidak.","say":["Alexa, minta Muslim Companion kaedah pengiraan mana yang patut saya guna"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"Cara lain untuk bertanya tentang tetapan anda.","say":["Alexa, minta Muslim Companion kaedah pengiraan apa yang saya guna","Alexa, minta Muslim Companion apakah mazhab saya"]},"Alexa, ask Muslim Companion to play athan":{"does":"Memainkan azan sekarang, diikuti doa dan Al-Quran pilihan anda. Suara yang boleh disebut termasuk Makkah, Madinah, Mishary dan Zahrani.","say":["Alexa, minta Muslim Companion mainkan azan","Alexa, minta Muslim Companion mainkan azan Makkah"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"Memainkan azan solat itu (Subuh menggunakan suara azannya sendiri).","say":["Alexa, minta Muslim Companion mainkan azan Subuh","Alexa, minta Muslim Companion mainkan azan Maghrib"]},"Alexa, ask Muslim Companion to test athan":{"does":"Memainkan azan sekali supaya anda boleh menyemak bunyinya pada Echo ini.","say":["Alexa, minta Muslim Companion uji azan"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Memberitahu sama ada azan automatik dihidupkan.","say":["Alexa, minta Muslim Companion apakah status azan berjadual saya"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Menghidupkan azan automatik. Ia dimainkan pada setiap waktu solat melalui rutin Alexa anda (lihat Panduan Persediaan).","say":["Alexa, minta Muslim Companion hidupkan azan berjadual"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"Mematikan azan automatik untuk semua solat sehingga anda menghidupkannya semula.","say":["Alexa, minta Muslim Companion matikan azan berjadual"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Memainkan mana-mana surah mengikut nama atau nombor, disebut cara anda menyebutnya (Fatiha atau Fateha, Baqarah atau Surah Baqara, Nisa\u2026), dengan qari anda atau qari yang anda sebut (Qari Badar, Maher, Al-Muaiqly, Sudais\u2026), atau dengan terjemahan Inggeris atau Urdu selepas setiap ayat.","say":["Alexa, minta Muslim Companion mainkan Surah Al-Kahfi","Alexa, minta Muslim Companion mainkan Surah Al-Baqarah oleh Qari Badar","Alexa, minta Muslim Companion mainkan Al-Fatihah oleh Maher","Alexa, minta Muslim Companion mainkan surah nombor 36","Alexa, minta Muslim Companion mainkan Surah Yasin dengan terjemahan Inggeris"]},"Alexa, ask Muslim Companion which reciters do you have":{"does":"Menyenaraikan qari, atau yang namanya bermula dengan sesuatu huruf. Jika Alexa tidak mengenali qari yang anda sebut, ia mencadangkan yang bermula dengan huruf yang sama.","say":["Alexa, minta Muslim Companion qari apa yang ada","Alexa, minta Muslim Companion qari mana yang bermula dengan S"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Setiap Jumaat, Surah Al-Kahfi dimainkan selepas azan Subuh (atau Zohor, ditetapkan di papan pemuka).","say":["Alexa, minta Muslim Companion hidupkan Al-Kahfi hari Jumaat","Alexa, minta Muslim Companion matikan Al-Kahfi hari Jumaat"]},"Alexa, next":{"does":"Semasa Al-Quran dimainkan: surah seterusnya atau sebelumnya. Semasa azan dan doa, Seterusnya melangkau ke hadapan.","say":["Alexa, seterusnya","Alexa, sebelumnya"]},"Alexa, start over":{"does":"Memulakan semula surah semasa.","say":["Alexa, mula semula"]},"Alexa, pause":{"does":"Menjeda bacaan dan menyambung dari tempat yang sama.","say":["Alexa, jeda","Alexa, sambung"]},"Alexa, stop":{"does":"Menghentikan azan atau bacaan pada bila-bila masa.","say":["Alexa, berhenti","Alexa, batal"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Memberitahu Perjalanan Al-Quran anda: masa mendengar dan berapa banyak khatam yang telah anda dengar.","say":["Alexa, minta Muslim Companion sejauh mana saya dalam Al-Quran"]},"Alexa, shuffle":{"does":"Menerangkan cara memilih Al-Quran rawak atau berterusan di halaman Jadual Al-Quran.","say":["Alexa, rawak","Alexa, ulang"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Memainkan pelajaran semasa anda: setiap ayat diulang, kemudian keseluruhan pelajaran bersama. Pada Echo Show ayat dipaparkan di skrin.","say":["Alexa, minta Muslim Companion mulakan hafazan"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Menandakan pelajaran sudah dihafaz dan beralih ke pelajaran seterusnya.","say":["Alexa, beritahu Muslim Companion saya sudah menghafaznya"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"Menetapkan berapa kali setiap ayat diulang: 1, 3, 5, 7 atau 10.","say":["Alexa, minta Muslim Companion ulang setiap ayat lima kali"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Memberitahu berapa ayat yang telah anda hafaz dan pelajaran semasa anda.","say":["Alexa, minta Muslim Companion bagaimana hafazan saya"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Menyebut waktu iqamah seterusnya di masjid yang anda ikuti.","say":["Alexa, minta Muslim Companion bilakah iqamah"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Menyebut waktu solat Jumaat minggu ini di masjid anda.","say":["Alexa, minta Muslim Companion bilakah solat Jumaat"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Menghidupkan atau mematikan mod Ramadan: peringatan sahur, berbuka pada Maghrib dan bacaan Tarawih selepas Isyak.","say":["Alexa, minta Muslim Companion hidupkan mod Ramadan","Alexa, minta Muslim Companion matikan mod Ramadan"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Memberitahu sama ada mod Ramadan dihidupkan.","say":["Alexa, minta Muslim Companion adakah mod Ramadan dihidupkan"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Menyebut bila sahur berakhir (Subuh) dan bila berbuka (Maghrib).","say":["Alexa, minta Muslim Companion bilakah sahur","Alexa, minta Muslim Companion bilakah berbuka"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Menyebut arah kiblat dari lokasi tersimpan dalam darjah dari utara benar dan sebagai arah kompas, serta jarak ke Makkah.","say":["Alexa, minta Muslim Companion ke arah mana kiblat","Alexa, minta Muslim Companion di manakah kiblat"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Menyebut tarikh Hijrah hari ini (sama dengan apl dan Echo Show anda), dan jika hari ini hari istimewa.","say":["Alexa, minta Muslim Companion apakah tarikh Hijrah","Alexa, minta Muslim Companion apakah tarikh Islam hari ini"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"Bila Ramadan, Hari Raya, Asyura, Arafah, Tahun Baru Hijrah, sepuluh malam terakhir atau hari-hari putih, dengan kiraan detik. Tarikh mengikut Umm al-Qura dan boleh berbeza sehari jika anak bulan dilihat secara tempatan.","say":["Alexa, minta Muslim Companion bilakah Ramadan","Alexa, minta Muslim Companion berapa hari lagi ke Hari Raya","Alexa, minta Muslim Companion bilakah hari-hari putih"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"Puasa sunat seterusnya: Isnin dan Khamis, hari-hari putih, Arafah, Asyura dan enam hari Syawal.","say":["Alexa, minta Muslim Companion bilakah puasa sunat seterusnya","Alexa, minta Muslim Companion patutkah saya berpuasa esok"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"Peringatan selepas Isyak pada malam sebelum puasa sunat, melalui rutin Muslim Companion anda.","say":["Alexa, minta Muslim Companion hidupkan peringatan puasa","Alexa, minta Muslim Companion matikan peringatan puasa"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"Ayat Kursi, kemudian Al-Ikhlas, Al-Falaq dan An-Nas tiga kali setiap satu, dibacakan.","say":["Alexa, minta Muslim Companion mainkan zikir pagi","Alexa, minta Muslim Companion mainkan zikir petang"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Memainkan zikir pagi selepas Subuh dan zikir petang selepas Asar setiap hari (atau Maghrib, ditetapkan di papan pemuka).","say":["Alexa, minta Muslim Companion hidupkan zikir pagi dan petang","Alexa, minta Muslim Companion matikan zikir petang"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Mengira zikir bersama anda dengan rentak perlahan. Tanpa zikir disebut, ia memimpin tasbih selepas solat: 33 Subhanallah, 33 Alhamdulillah dan 34 Allahu Akbar. Pada Echo Show, ketik skrin untuk mengira.","say":["Alexa, minta Muslim Companion mulakan tasbih","Alexa, minta Muslim Companion kira 33 subhanallah"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"Doa, hadis atau Nama Allah harian yang ringkas bersama sumbernya, disemak oleh ulama sebelum diterbitkan.","say":["Alexa, minta Muslim Companion doa hari ini","Alexa, minta Muslim Companion hadis hari ini","Alexa, minta Muslim Companion Nama Allah hari ini"],"soonNote":"Akan datang: setiap doa, hadis dan Nama disemak oleh ulama terlebih dahulu"},"Alexa, open Muslim Companion":{"does":"Memulakan skill (ia memainkan azan untuk solat semasa).","say":["Alexa, buka Muslim Companion"]},"Alexa, ask Muslim Companion for help":{"does":"Menyenaraikan apa yang boleh anda tanya.","say":["Alexa, minta Muslim Companion bantuan"]},"Alexa, ask Muslim Companion to link my phone":{"does":"Memautkan Echo ini kepada akaun Salat-e-Mustaqeem di telefon dengan kod enam digit daripada aplikasi (Lagi, kemudian Alexa), supaya kemajuan Hifz anda dipaparkan di telefon.","say":["Alexa, minta Muslim Companion pautkan telefon saya","Alexa, minta Muslim Companion pautkan telefon saya dengan kod 123456"]}}}')}}]);